/* ===== Аня: продолжение программы (декабрь — март). Виленкин 5–6 кл. (1990); Ладыженская 5–6 кл.; Агибалова, Донской. История Средних веков (1988); география 5–6 кл. ===== */
const FS = (n, d) => { const g = U.gcd(n, d) || 1; n /= g; d /= g; return d === 1 ? String(n) : `${n}/${d}`; };
const MXS = (n, d) => { const w = Math.floor(n / d), m = n % d; return !m ? String(w) : w ? `${w} ${m}/${d}` : `${m}/${d}`; };
/* Ответ-дробь: сокращаем и выделяем целую часть (17/15 → 1 2/15). ex — типичные ошибки [числитель, знаменатель], идут первыми */
const FM = (n, d) => { const g = U.gcd(n, d) || 1; return MXS(n / g, d / g); };
function frC(q, n, d, r, e, ex){ const v = n / d, a = FM(n, d), w = [];
  for (const [x, y] of (ex || []).concat(r.shuffle([[n + d, d], [n, d + 1], [n + 1, d], [Math.max(1, n - 1), d], [n, d * 2], [n * 2, d]]))) { if (x > 0 && y > 0 && Math.abs(x / y - v) > 1e-9) { const s = FM(x, y); if (s !== a && !w.includes(s)) w.push(s); } if (w.length === 3) break; }
  if (/^\d+$/.test(a) && w.every(x => /^\d+$/.test(x))) return C(q, NK(a), w.map(NK), e);
  return C(q, a, w, e); }

